      if (!fs || !sh) return;
      const vr = fs.getBoundingClientRect();
      const contentHeight = Math.max(620, sh.scrollHeight || 620);
      const scale = Math.max(0.36, Math.min(1, (vr.width - 16) / 1280, (vr.height - 16) / contentHeight) * 0.96);
      const isMobileViewport = window.matchMedia('(max-width: 1024px)').matches;
      if (isMobileViewport) {
        const scaledHeight = contentHeight * scale;
        const offsetTop = Math.max(0, (vr.height - scaledHeight) / 2);
        sh.style.top = offsetTop + 'px';
        sh.style.transform = 'translateX(-50%) scale(' + scale + ')';
      } else {
        sh.style.top = '0';
        sh.style.transform = 'translateX(-50%) scale(' + scale + ')';
      }
